import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

const getPasswordStrength = (password) => {
  if (password.length < 6) return 'Weak';
  if (password.match(/[A-Z]/) && password.match(/[0-9]/) && password.match(/[\W]/))
    return 'Strong';
  return 'Medium';
};

function App() {
  const [tab, setTab] = useState('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [token, setToken] = useState(null);

  const handleAuth = async () => {
    const endpoint = tab === 'login' ? 'login' : 'signup';
    try {
      const res = await axios.post(`http://localhost:5000/api/${endpoint}`, {
        email,
        password,
      });
      setToken(res.data.token);
      alert(`${tab === 'login' ? 'Login' : 'Signup'} successful`);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div className="container">
      <div className="tabs">
        <button
          className={tab === 'login' ? 'active' : ''}
          onClick={() => {
            setTab('login');
            setEmail('');
            setPassword('');
            setToken(null);
          }}
        >
          Login
        </button>
        <button
          className={tab === 'signup' ? 'active' : ''}
          onClick={() => {
            setTab('signup');
            setEmail('');
            setPassword('');
            setToken(null);
          }}
        >
          Signup
        </button>
      </div>

      <h2>{tab === 'login' ? 'Login' : 'Create Account'}</h2>

      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />

      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
      />

      {tab === 'signup' && (
        <div className={`strength ${getPasswordStrength(password).toLowerCase()}`}>
          Strength: {getPasswordStrength(password)}
        </div>
      )}

      <button onClick={handleAuth}>
        {tab === 'login' ? 'Log In' : 'Sign Up'}
      </button>

      {token && (
        <div className="token-box">
          <strong>JWT Token:</strong>
          <p>{token}</p>
        </div>
      )}
    </div>
  );
}

export default App;
